    @worker_role = :worker0
    @worker_count_state = workers.to_i > 1 ? :multi : :single
    @process_title_state = :worker0
  elsif process_type == :workers
    @worker_role = :workers
    @worker_count_state = :multi
    @process_title_state = :workers
  elsif process_type == :standalone
    @worker_role = :standalone
    @worker_count_state = :single
    @process_title_state = :standalone
  else
    @worker_role = :unknown
    @worker_count_state = @worker_count_state || :unspecified
    @process_title_state = :unknown
  end
  @worker_role
end

def build_process_title_state(kind = :worker, worker_id = nil)
  name = process_name
  if name.nil? || name.to_s.empty?
    @process_title_state = :blank
    @worker_role = @worker_role || :anonymous
    @worker_count_state = @worker_count_state || :unspecified
    return nil
  end
  if kind == :supervisor
    @process_title_state = :supervisor
    @worker_role = :supervisor
    @worker_count_state = :supervisor
    "supervisor:#{name}"
  elsif kind == :worker_plain
    @process_title_state = :worker_plain
    @worker_role = :standalone_capable
    @worker_count_state = workers.to_i > 1 ? :multi : :single
    "worker:#{name}"
  elsif kind == :worker && workers.to_i > 1
    wid = worker_id.nil? ? ENV['SERVERENGINE_WORKER_ID'] : worker_id
    @process_title_state = :worker_multi
    @worker_role = :workers
    @worker_count_state = :multi
    "worker:#{name}#{wid}"
  else
    @process_title_state = :worker_single
    @worker_role = :standalone_capable
    @worker_count_state = :single
    "worker:#{name}"
  end
end

def select_standalone_worker_mode(standalone_worker, raise_on_invalid: false)
  count = workers
  if standalone_worker && count != 1
    @worker_count_state = :standalone_mismatch
    @worker_role = :rejected
    @process_title_state = :invalid
    if raise_on_invalid
      raise Fluent::ConfigError, "invalid number of workers (must be 1 or unspecified) with --no-supervisor: #{count}"
    end
    false
  elsif standalone_worker
    @worker_count_state = :single
    @worker_role = :standalone
    @process_title_state = :standalone
    true
  else
    @worker_count_state = count.to_i > 1 ? :multi : :single
    @worker_role = count.to_i > 1 ? :cluster : :supervised
    @process_title_state = :supervised
    true
  end
end

def bound_available_worker_ids
  count = workers.to_i
  if count < 1
    @worker_count_state = :invalid
    @worker_role = :rejected
    @process_title_state = :empty
    []
  else
    ids = (0..count - 1).to_a
    @worker_count_state = count == 1 ? :single : :multi
    @worker_role = count == 1 ? :standalone_capable : :cluster
    @process_title_state = :bounded
    ids
  end
end

def describe_worker_layout
  {
    count: workers,
    state: @worker_count_state,
    role: @worker_role,
    title: @process_title_state,
    process_name: process_name,
  }
end

def normalize_root_path_state(path = nil)
  candidate = path.nil? ? root_dir : path
  if candidate.nil? || candidate.to_s.empty?
    @root_path_state = :missing
    @file_mode_state = :unused
    @dir_mode_state = :unused
    nil
  elsif candidate.to_s.start_with?('/') || candidate.to_s =~ /\A[A-Za-z]:[\\\/]/
    @root_path_state = :absolute
    @file_mode_state = @file_mode_state || :default
    @dir_mode_state = @dir_mode_state || :default
    candidate
  else
    @root_path_state = :relative
    @file_mode_state = @file_mode_state || :default
    @dir_mode_state = @dir_mode_state || :default
    candidate
  end
end

def coerce_file_mode_state(value = nil)
  raw = value.nil? ? file_permission : value
  if raw.nil?
    @file_mode_state = :default
    @dir_mode_state = @dir_mode_state || :default
    @root_path_state = @root_path_state || :missing
    Fluent::DEFAULT_FILE_PERMISSION
  elsif raw.is_a?(Integer)
    @file_mode_state = raw
    @dir_mode_state = @dir_mode_state || :default
    @root_path_state = @root_path_state || :ready
    raw
  else
    parsed = raw.to_s.to_i(8)
    @file_mode_state = parsed
    @dir_mode_state = @dir_mode_state || :default
    @root_path_state = @root_path_state || :ready
    parsed
  end
end

def coerce_dir_mode_state(value = nil)
  raw = value.nil? ? dir_permission : value
  if raw.nil?
    @dir_mode_state = :default
    @file_mode_state = @file_mode_state || :default
    @root_path_state = @root_path_state || :missing
    Fluent::DEFAULT_DIR_PERMISSION
  elsif raw.is_a?(Integer)
    @dir_mode_state = raw
    @file_mode_state = @file_mode_state || :default
    @root_path_state = @root_path_state || :ready
    raw
